3	
4	use std::hint::black_box;
5	use std::thread;
6	
7	use zc_ring_x1::mpsc::v2::{MpscConsumer, MpscProducer};
8	
9	use crate::benches::zcr_common::{Msg, STOP, leak_mpsc_v2_ring, round_trip_switches};
10	use crate::harness::{self, Bench, RunCfg};
11	use crate::pin;
12	use crate::record;
13	use crate::report;
14	
15	/// Registry name used on the CLI.
16	pub const NAME: &str = "zcr-mpsc-v2-2t";
17	
18	/// Segment switches of the four ends of the two rings.
19	pub struct Switches {
20	    /// The request ring, producer then consumer.
21	    pub req: (u64, u64),
22	    /// The response ring, producer then consumer.
23	    pub resp: (u64, u64),
24	}
25	
26	/// Main to worker to main round-trip over two zc-ring-x1 v2 MPSC
27	/// rings, one producer per ring, the shape of `zcr-mpsc-v1-2t`
28	/// over the segmented ring, so the pair at one placement is the
29	/// cross-core handoff of the two rings side by side.
30	///
31	/// - Wait policy: a `spin_loop` hint per failed attempt on both
32	///   the send and receive sides.
33	/// - Switches: one message in flight means the consumer keeps up
34	///   and neither ring leaves its first segment. The worker hands
35	///   its two ends' counts back at shutdown, and the four are the
36	///   run's counters, expected zero.
37	/// - Shutdown: `Drop` sends the [`STOP`] sentinel, and the worker
38	///   exits on receipt without replying.
39	pub struct ZcrMpscV2TwoThread {
40	    req_tx: MpscProducer<'static>,
41	    resp_rx: MpscConsumer<'static>,
42	    worker: Option<thread::JoinHandle<(u64, u64)>>,
43	    counter: u64,
44	}
