61	/// `trait SendPolicy` is what a [`send`](MpscProducer::send) does when the ring is full, and when
62	/// another producer takes a slot first.
63	///
64	/// - A closure `FnMut(u32) -> bool` is a `SendPolicy`: its argument is the attempt count and its
65	///   result is [`on_full`](SendPolicy::on_full)'s, so `|attempt| attempt < 100` gives up after a
66	///   hundred full looks, and [`policy::spin`](crate::policy::spin) never gives up.
67	/// - A type implementing `SendPolicy` also sees each lost slot, and can sleep through [`Room`].
68	/// - A send takes its policy by value. A policy whose state the caller reads afterward, such as a
69	///   count, implements `SendPolicy` for `&mut` itself.
70	pub trait SendPolicy {
71	    /// `on_full` is called each time a send finds the ring full.
72	    ///
73	    /// # Parameters
74	    ///
75	    /// - `self`: the policy, by mutable reference, so it can keep state across calls, such as a
76	    ///   deadline or a count.
77	    /// - `attempt`: how many times this send has found the ring full before, `0` the first time,
78	    ///   saturating.
79	    /// - `room`: sleeps until the consumer frees a slot, for a policy that would rather sleep than
80	    ///   spin.
81	    ///
82	    /// # Returns
83	    ///
84	    /// - `true` to look at the ring again, or `false` to give up, and the send returns `Err(Full)`.
85	    fn on_full(&mut self, attempt: u32, room: &Room<'_>) -> bool;
86	
87	    /// `on_lost` is called each time another producer takes a slot this send was about to claim.
88	    /// The send then looks again at once, and does not call `on_full`: a lost slot is never a full
89	    /// ring.
90	    ///
91	    /// # Parameters
92	    ///
93	    /// - `self`: the policy, by mutable reference.
94	    /// - `lost`: how many slots this send has lost in a row, `1` the first time, saturating.
95	    ///
96	    /// # Notes
97	    ///
98	    /// - By default `on_lost` does nothing. A policy backs off here, with
99	    ///   [`policy::backoff`](crate::policy::backoff), or counts contention.
100	    fn on_lost(&mut self, _lost: u32) {}
101	}
