258	    /// - `Err(Full)`: the ring stayed full until `spin_time` and `sleep_time` passed. No slot was
259	    ///   claimed, and `write_msg` was not called.
260	    #[cfg(any(target_os = "linux", feature = "std"))]
261	    pub fn send_spin_sleep<T>(
262	        &self,
263	        spin_time: Ticks,
264	        sleep_time: Ticks,
265	        write_msg: impl FnOnce(&mut T),
266	    ) -> Result<(), Full>
267	    where
268	        T: FromBytes + IntoBytes + KnownLayout,
269	    {
270	        // `ends` holds the spin's end and the sleep's end, set at the first full ring, so a send
271	        // that finds room reads no clock, and each later check is one reading and a compare or two.
272	        let mut ends: Option<(u64, u64)> = None;
273	        self.send(
274	            |_| {
275	                if spin_time == Ticks::FOREVER {
276	                    core::hint::spin_loop();
277	                    return true;
278	                }
279	                let now = now_ticks();
280	                let (spin_end, sleep_end) = *ends.get_or_insert_with(|| {
