///
/// - [`release`](MpscConsumer::release) gives the role back with the consumer's state, so the next
///   claim continues where this one stopped. Dropping the handle writes nothing, so the role stays
///   held.
pub struct MpscConsumer<'a, M: Mode = Multi, W: Wake = NoWake> {
    /// Private state, borrowed by each guard.
    st: ConsumerState,
    _region: PhantomData<(&'a [u8], M, W)>,
}

// SAFETY: the handle owns the single-consumer role, and shared state (the header words, the slot
// seqs) is atomic with Release/Acquire handoff.
unsafe impl<M: Mode, W: Wake> Send for MpscConsumer<'_, M, W> {}

impl<'a, M: Mode, W: Wake> MpscConsumer<'a, M, W> {
    /// Continue from `cp`, the checkpoint the last consumer left, or the ring's start.
    pub(super) fn resume(segs: Segments, cp: Checkpoint) -> Self {
        MpscConsumer {
            st: ConsumerState {
                segs,
                cur: cp.cur,
                pos: cp.pos,
                resume: cp.resume,
                switches: 0,
            },
            _region: PhantomData,
        }
    }

    /// Give the consumer role back, with its state.
    ///
    /// - Writes the segment, the position, and each segment's resume position into the control
    ///   block, then clears the role, so the next claim, in any process, continues exactly here.
    pub fn release(self) {
        let st = &self.st;
        st.segs.store_consumer(&Checkpoint {
            cur: st.cur,
            pos: st.pos,
            resume: st.resume,
        });
        // Release: the next claim's AcqRel sees the checkpoint and every release of a slot before
        // it.
        st.segs.roles().fetch_and(!CONSUMER, Ordering::Release);
    }

    /// Segment switches this consumer has made: how many seals it has followed since its claim.
    /// Once it has read everything sent, a consumer claimed on a new ring equals the producers'
    /// count.
    pub fn switches(&self) -> u64 {
        self.st.switches
    }

    /// The segment this consumer reads from, `0` to the ring's segment count less one.
    pub fn segment(&self) -> u32 {
        self.st.cur
    }

    /// Reserve the oldest committed slot as a `&T`, applying an injected wait policy: retry until a
    /// message arrives or the policy gives up, then [`Empty`].
    ///
    /// - The slot at the position is committed or not. Not means a second look at the segment's
    ///   seal: MOVED with the end position equal to this one means the segment has ended, so it is
    ///   given back and the reading continues in the named segment, progress again. Otherwise the
    ///   slot is not yet committed and the policy runs. So a segment is given back at the reserve
    ///   after its last release, not at that release: the fast path never loads the seal, and a
    ///   [`Single`](super::Single) ring never does.
    /// - A seal naming a segment the ring does not have reads as Empty, failing toward Empty as the
    ///   rings do.
    /// - `on_empty` is called after each failed attempt with the attempt count (0-based,
    ///   saturating), and returning `false` gives up. Pass `|_| false` for a single non-blocking
    ///   probe.
    /// - Guard semantics as v1's: drop without release re-delivers the same slot.
    pub fn reserve_slot_with<T>(
        &mut self,
        on_empty: impl FnMut(u32) -> bool,
    ) -> Result<MpscReadSlot<'_, T, W>, Empty>
    where
        T: FromBytes + KnownLayout + Immutable,
    {
        self.reserve(on_empty, false)
    }

    /// [`reserve_slot_with`](MpscConsumer::reserve_slot_with), sleeping on an empty ring until a
    /// producer commits, then calling `on_empty` after each wake.
    ///
    /// - The sleep is `W`'s: with [`NoWake`] it is a spin, and with a futex it returns when a
    ///   producer wakes it or at its timeout, so `on_empty` also counts the timeouts, and bounds
    ///   the wait as it bounds a spin. Pass `|_| true` to wait until a message arrives.
    /// - A wake can come between a producer's claim and its commit, and the look after it then
    ///   finds the slot claimed and not yet committed, which does not sleep again, so the policy
    ///   runs until the commit lands.
    /// - Before each sleep, producers asleep on a full ring are woken, so two sides never sleep on
    ///   each other past a missed check.
    pub fn reserve_slot_wait<T>(
        &mut self,
        on_empty: impl FnMut(u32) -> bool,
    ) -> Result<MpscReadSlot<'_, T, W>, Empty>
    where
        T: FromBytes + KnownLayout + Immutable,
    {
        self.reserve(on_empty, true)
    }

    /// The reserve both entries share, sleeping on an empty ring when `sleep` is set.
    #[inline(always)]
    fn reserve<T>(
        &mut self,
        mut on_empty: impl FnMut(u32) -> bool,
        sleep: bool,
    ) -> Result<MpscReadSlot<'_, T, W>, Empty>

