///   exits on receipt without replying.
pub struct ZcrMpscV3TwoThread<M: Mode, W: Wake> {
    req_tx: MpscProducer<'static, M, W>,
    resp_rx: MpscConsumer<'static, M, W>,
    worker: Option<thread::JoinHandle<(u64, u64)>>,
    counter: u64,
